def api_fn(name, service, data_props, desc, timeout=20000):
    return {
        "type": "function",
        "config": {"timeoutMs": timeout, "maxRetries": 0},
        "function": {
            "name": name, "handler": "__function__:api_call", "description": desc,
            "parameters": {"type": "object", "properties": {
                "url": {"type": "string", "default": M + service},
                "method": {"type": "string", "default": "POST"},
                "headers": HDR,
                "body": {"type": "object", "properties": {
