                    "call": {"type": "object", "properties": {"lang": {"type": "string", "default": "tr"}}}}}}}}}


def S(v):
    return {"type": "string", "default": v}


def cond(*cs):
    return {"logic": "or", "conditions": list(cs)}


def eq(v, o):
    return {"variable": v, "operator": "equals", "operand": o}


def T(target, desc, c=None):
    return {"target_node": target, "description": desc, "condition": c or {"operator": "always"}}


def I(target, desc):
    return {"target_node": target, "description": desc, "condition": {"operator": "matches_intent", "description": desc}}


def api_node(name, fn, mapping, transitions, say=None):
    assert "{{" not in json.dumps(mapping)
    return {"name": name, "node_type": "api_request", "passthrough": True,
            "passthrough_default_transition": transitions[-1]["target_node"],
            "on_enter": {"type": "tts", "text": say} if say else {"type": "silent"},
            "disable_inactivity_monitor": True, "pre_actions": [fn], "response_mapping": mapping,
