    return {"name": name, "node_type": "code", "passthrough": True,
            "passthrough_default_transition": transitions[-1]["target_node"],
            "on_enter": {"type": "silent"}, "disable_inactivity_monitor": True,
            "pre_actions": [{"type": "function", "function": {
                "name": "code_exec", "handler": "__function__:code_exec",
                "parameters": {"type": "object", "properties": {
                    "code": {"type": "string", "default": code},
                    "timeout_ms": {"type": "number", "default": 10000}}}}}],
            "transitions": transitions}


def conv(name, task, transitions, on_enter=None, tools=None, turns=4, max_to="end_tries", extraction=None):
    n = {"name": name, "node_type": "conversation", "task_message": task,
         "on_enter": on_enter or {"type": "llm"}, "tools": tools or [],
         "transitions": transitions, "max_node_turns": turns, "max_turn_transition": max_to}
