    t = cn + ' hesap kesim tarihi her ayın ' + str(wk) + '. haftası olarak tanımlı. Bir sonraki hesap kesim tarihiniz ' + sd(vars.get('wk_nextStatementDate')) + ', son ödeme tarihiniz ' + sd(vars.get('wk_nextLastPayDate')) + '.'
    if rel in ('M', 'C') and rname:
        t += ' Bu kart, sonu ' + rl4 + ' ile biten ' + rname + ' kartınızla ortak ekstreye sahip; iki kartın hesap kesim haftası ve tarihleri aynıdır.'
        if rel == 'M':
            vars['joint_note'] = 'Bu değişiklik kartınıza bağlı ' + rname + ' kartınızı da etkileyecek. '
        else:
            vars['joint_note'] = 'Bu değişiklik kartınızın bağlı olduğu ' + rname + ' kartınızı da etkileyecek. '
    else:
        vars['joint_note'] = ''
    vars['week_intro'] = t
    vars['week_options_text'] = 'Hesap kesim tarihinizi ayın ' + opts[0] + '., ' + opts[1] + '. ya da ' + opts[2] + '. haftasına alabilirim. Hangisini tercih edersiniz?'
    vars['week_state'] = 'pending'
    vars['confirm_tries'] = '0'
    vars['week_prep_state'] = 'ok'
except Exception:
    vars['week_prep_state'] = 'error'
'''

CHOOSE_WEEK = COMMON + r'''
w = r"""{{week}}"""
'''
CHOOSE_BODY = r'''
try:
    m = re.search('[1-4]', w)
    wl = w.lower()
    for k, v in (('bir', '1'), ('ilk', '1'), ('iki', '2'), ('üç', '3'), ('uc', '3'), ('dört', '4'), ('dort', '4'), ('son', '4')):
        if not m and k in wl:
            m = v
            break
    n = m.group(0) if hasattr(m, 'group') else (m or '')
    opts = str(vars.get('week_options') or '').split(',')
    if n and n == str(vars.get('current_week')):
        vars['week_state'] = 'current'
    elif n in opts and n:
        vars['new_week'] = n
        vars['week_state'] = 'valid'
    else:
        vars['week_state'] = 'invalid'
except Exception:
    vars['week_state'] = 'invalid'
'''

PREVIEW_PREP = COMMON + r'''
AYLAR = ['', 'Ocak', 'Şubat', 'Mart', 'Nisan', 'Mayıs', 'Haziran', 'Temmuz', 'Ağustos', 'Eylül', 'Ekim', 'Kasım', 'Aralık']
DIG = ['sıfır', 'bir', 'iki', 'üç', 'dört', 'beş', 'altı', 'yedi', 'sekiz', 'dokuz']
def sd(s):
    d, m, y = str(s).strip().split('.')
    return str(int(d)) + ' ' + AYLAR[int(m)] + ' ' + y
try:
    a = sd(vars.get('pv_statementDate'))
    b = sd(vars.get('pv_statementDueDate'))
    w = str(vars.get('new_week'))
    vars['week_confirm_text'] = str(vars.get('joint_note') or '') + 'Yeni hesap kesim haftanız her ayın ' + w + '. haftası olacak. Yeni hesap kesim tarihiniz ' + a + ', son ödeme tarihiniz ' + b + ' olacak. Onaylıyor musunuz?'
    name = str(vars.get('selected_name') or '')
    l4 = ' '.join(DIG[int(c)] for c in str(vars.get('selected_last4') or '') if c.isdigit())
    vars['week_done_text'] = 'Sonu ' + l4 + ' ile biten ' + (name + ' ' if name else '') + 'kartınızın hesap kesim haftası her ayın ' + w + '. haftası olarak değiştirildi. Yeni hesap kesim tarihiniz ' + a + ', son ödeme tarihiniz ' + b + '. Sizi ana menüye yönlendiriyorum.'
    vars['preview_state'] = 'ok'
except Exception:
    vars['preview_state'] = 'error'
'''

