import json

M = "https://yz50-bank-mock.kirgilmert.workers.dev/voice/v1/"
HDR = {"type": "object", "properties": {
    "Content-Type": {"type": "string", "default": "application/json"},
    "Accept": {"type": "string", "default": "application/json"},
    "Authorization": {"type": "string", "default": "Bearer test-token"}}}


def api_fn(name, service, data_props, desc, timeout=20000):
    return {
        "type": "function",
        "config": {"timeoutMs": timeout, "maxRetries": 0},
        "function": {
            "name": name, "handler": "__function__:api_call", "description": desc,
            "parameters": {"type": "object", "properties": {
                "url": {"type": "string", "default": M + service},
                "method": {"type": "string", "default": "POST"},
                "headers": HDR,
                "body": {"type": "object", "properties": {
                    "data": {"type": "object", "properties": data_props},
                    "call": {"type": "object", "properties": {"lang": {"type": "string", "default": "tr"}}}}}}}}}


def S(v):
    return {"type": "string", "default": v}


def cond(*cs):
    return {"logic": "or", "conditions": list(cs)}


def eq(v, o):
    return {"variable": v, "operator": "equals", "operand": o}


def T(target, desc, c=None):
    return {"target_node": target, "description": desc, "condition": c or {"operator": "always"}}


def I(target, desc):
    return {"target_node": target, "description": desc, "condition": {"operator": "matches_intent", "description": desc}}


def api_node(name, fn, mapping, transitions, say=None):
    assert "{{" not in json.dumps(mapping)
    return {"name": name, "node_type": "api_request", "passthrough": True,
            "passthrough_default_transition": transitions[-1]["target_node"],
            "on_enter": {"type": "tts", "text": say} if say else {"type": "silent"},
            "disable_inactivity_monitor": True, "pre_actions": [fn], "response_mapping": mapping,
            "transitions": transitions}


def code_node(name, code, transitions):
    assert "{{" not in code and "}}" not in code, name
    return {"name": name, "node_type": "code", "passthrough": True,
            "passthrough_default_transition": transitions[-1]["target_node"],
            "on_enter": {"type": "silent"}, "disable_inactivity_monitor": True,
            "pre_actions": [{"type": "function", "function": {
                "name": "code_exec", "handler": "__function__:code_exec",
                "parameters": {"type": "object", "properties": {
                    "code": {"type": "string", "default": code},
                    "timeout_ms": {"type": "number", "default": 10000}}}}}],
            "transitions": transitions}


def conv(name, task, transitions, on_enter=None, tools=None, turns=4, max_to="end_tries", extraction=None):
    n = {"name": name, "node_type": "conversation", "task_message": task,
         "on_enter": on_enter or {"type": "llm"}, "tools": tools or [],
         "transitions": transitions, "max_node_turns": turns, "max_turn_transition": max_to}
    if extraction:
        n["extraction_schema"] = extraction
    return n


def end(name, fname, msg):
    return {"name": name, "node_type": "end_call", "on_enter": {"type": "silent"},
            "disable_inactivity_monitor": True, "transitions": [],
            "terminal": {"type": "function", "function": {
                "name": fname, "handler": "__function__:end_call",
                "parameters": {"type": "object", "properties": {
                    "message_mode": S("custom" if msg else "none"),
                    **({"spoken_message": S(msg)} if msg else {})}}}}}


